export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Customer {
  yearsWithMHPCO: number;
}

const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const COMPONENT_TYPES = new Set(['rune', 'moonstone']);
const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

export function quote(items: Item[], customer: Customer, contractIndex: number): number {
  let base = 0;
  let surcharges = 0;
  for (const item of items) {
    const itemBase = BASE_PREMIUM[item.type];
    base += itemBase;
    if (item.cursed === true) {
      surcharges += itemBase * 0.5;
    }
    if (item.enchantment !== undefined && item.enchantment >= 5) {
      surcharges += itemBase * 0.3;
    }
  }
  base -= blockDiscount(items);
  let policyAdjustments = base * 0.1;
  if (customer.yearsWithMHPCO >= 2) {
    policyAdjustments -= base * 0.2;
  }
  if (contractIndex > 0) {
    policyAdjustments -= base * 0.15;
  }
  return base + surcharges + policyAdjustments + 5;
}

function blockDiscount(items: Item[]): number {
  const counts = new Map<string, number>();
  for (const item of items) {
    if (COMPONENT_TYPES.has(item.type)) {
      counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
    }
  }
  let discount = 0;
  for (const [type, count] of counts) {
    if (count === BLOCK_SIZE) {
      discount += BASE_PREMIUM[type] * BLOCK_SIZE - BLOCK_PREMIUM;
    }
  }
  return discount;
}

