import type { Item } from './quote.js';

const INSURANCE_VALUE: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

export function insuranceSum(items: Item[]): number {
  let sum = 0;
  for (const item of items) {
    sum += INSURANCE_VALUE[item.type];
  }
  return sum;
}

const DEDUCTIBLE = 100;

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export class Policy {
  private remainingCap: number;

  constructor(private readonly items: Item[]) {
    this.remainingCap = insuranceSum(items) * 2;
  }

  claim(incident: Incident): ClaimResult {
    let desired = 0;
    const available = [...this.items];
    for (const damage of incident.damages) {
      if (damage.amount < 0) {
        throw new Error(`negative damage amount: ${damage.amount}`);
      }
      const index = available.findIndex((candidate) => candidate.type === damage.itemType);
      if (index === -1) {
        throw new Error(`item not covered by the policy: ${damage.itemType}`);
      }
      const [item] = available.splice(index, 1);
      let reimbursed = damage.amount;
      if (item.enchantment !== undefined && item.enchantment >= 8) {
        reimbursed *= 0.5;
      }
      desired += reimbursed - DEDUCTIBLE;
    }
    const payout = Math.min(desired, this.remainingCap);
    this.remainingCap -= payout;
    return { payout, remainingCap: this.remainingCap };
  }
}

